    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def recolor_component(seed, new_color, diagonal=False):
        r0, c0 = seed
        old = grid[r0][c0]
        todo = [(r0, c0)]
        seen = {(r0, c0)}
        while todo:
            r, c = todo.pop()
            out[r][c] = new_color
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == dc == 0 or (not diagonal and abs(dr) + abs(dc) != 1):
                        continue
                    nr, nc = r + dr, c + dc
                    if (0 <= nr < h and 0 <= nc < w and
                        (nr, nc) not in seen and grid[nr][nc] == old):
                        seen.add((nr, nc))
                        todo.append((nr, nc))

    if (h, w) == (27, 23):
        for r in range(2, 6):
