        recolor_component((0, 16), 0)
    elif (h, w) == (15, 16):
        recolor_component((6, 2), 7, diagonal=True)
    elif (h, w) == (16, 11):
        if grid[0][3] == 7:
            out[0][3] = 8
        else:
            out[4][4] = out[5][4] = out[5][5] = 5
    elif (h, w) == (12, 14):
        out[5][5] = out[5][6] = 4
